class Solution {
public:
    int minCapability(vector<int>& nums, int k) {
        int n = nums.size();
        int l = *min_element(nums.begin(), nums.end());
        int r = *max_element(nums.begin(), nums.end());
        while (l < r) {
            int mid = l + (r - l) / 2;
            int cnt = 0;
            int i = 0;
            while (i < n) {
                if (nums[i] <= mid) {
                    cnt++;
                    i += 2;
                } else {
                    i++;
                }
            }
            if (cnt >= k) {
                r = mid;
            } else {
                l = mid + 1;
            }
        }
        return l;
    }
};
